use rhwp::DocumentCore;
use rhwp::model::{document::Document,control::Control};
use serde_json::{Value,json};use sha2::{Digest,Sha256};use std::path::PathBuf;
fn sha(b:&[u8])->String{Sha256::digest(b).iter().map(|b|format!("{b:02x}")).collect()}
fn state(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|p|json!({"page":p,"controls":serde_json::from_str::<Value>(&d.get_page_control_layout_native(p).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(p).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn safe(v:&Value)->Value{match v{Value::Number(_)|Value::Null|Value::Bool(_)=>v.clone(),Value::String(s)=>json!({"kind":"string","characters":s.chars().count(),"sha256":sha(s.as_bytes())}),_=>json!({"kind":if v.is_array(){"array"}else{"object"},"sha256":sha(&serde_json::to_vec(v).unwrap())})}}
fn diff(a:&Value,b:&Value,p:&str,out:&mut Vec<Value>){match(a,b){(Value::Number(a),Value::Number(b))=>{let(x,y)=(a.as_f64().unwrap(),b.as_f64().unwrap());if !x.is_finite()||!y.is_finite()||(x-y).abs()>0.2{out.push(json!({"path":p,"before":a,"after":b}));}},(Value::Array(a),Value::Array(b))=>{if a.len()!=b.len(){out.push(json!({"path":format!("{p}/length"),"before":a.len(),"after":b.len()}));}for i in 0..a.len().max(b.len()){diff(a.get(i).unwrap_or(&Value::Null),b.get(i).unwrap_or(&Value::Null),&format!("{p}/{i}"),out);}},(Value::Object(a),Value::Object(b))=>{let keys:std::collections::BTreeSet<_>=a.keys().chain(b.keys()).collect();for k in keys{diff(a.get(k).unwrap_or(&Value::Null),b.get(k).unwrap_or(&Value::Null),&format!("{p}/{k}"),out);}},_=>if a!=b{out.push(json!({"path":p,"before":safe(a),"after":safe(b)}));}}}
fn native_ir(d:&DocumentCore)->Value {json!({"sections":d.document().sections.iter().map(|s|json!({"sectionDefinition":s.section_def,"paragraphs":s.paragraphs})).collect::<Vec<_>>(),"summary":serde_json::from_str::<Value>(&d.get_document_metadata_native()).unwrap(),"docInfoDebugSha256":sha(format!("{:?}",d.document().doc_info).as_bytes())})}
fn compare(a:&DocumentCore,b:&DocumentCore)->Value{let mut layout=vec![];diff(&state(a),&state(b),"pages",&mut layout);let mut ir=vec![];diff(&native_ir(a),&native_ir(b),"native-model",&mut ir);let mut fields=std::collections::BTreeMap::<String,usize>::new();for d in &layout{let key=d["path"].as_str().unwrap().rsplit('/').next().unwrap();*fields.entry(key.into()).or_default()+=1;}
json!({"beforePages":a.page_count(),"afterPages":b.page_count(),"publishedGeometryDifferences":layout.len(),"publishedDifferenceFields":fields,"firstPublishedDifferences":layout.iter().take(20).collect::<Vec<_>>(),"nativeModelDifferences":ir.len(),"firstNativeModelDifferences":ir.iter().take(20).collect::<Vec<_>>(),"nativeModelIsProductionSemanticReader":false})}
#[test]fn actual_v7_hancom_resave_three_axes_read_only(){let repo=PathBuf::from(std::env::var("JUEONY_REPO").unwrap());let out=repo.join("build/mcst-cross-closure77");let names=["build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx","build/mcst-cross-closure77/mcst-actual-v7-final-native-review.hwp","build/mcst-cross-closure77/mcst-v7-final-native-hancom-resaved.hwpx"];
let mut bytes=vec![];let mut inputs=vec![];for name in names{let b=std::fs::read(repo.join(name)).unwrap();inputs.push(json!({"path":name,"bytes":b.len(),"sha256":sha(&b)}));bytes.push(b);}let docs:Vec<_>=bytes.iter().map(|b|DocumentCore::from_bytes(b).unwrap()).collect();let mut cycles=vec![];for codec in["hwp","hwpx"]{let artifact=if codec=="hwp"{docs[2].export_hwp_with_adapter_snapshot_with_report().unwrap()}else{docs[2].export_hwpx_native_with_report().unwrap()};let loss=artifact.content_loss().is_empty();let r=DocumentCore::from_bytes(artifact.bytes()).unwrap();cycles.push(json!({"codec":codec,"lossEmpty":loss,"outputSha256":sha(artifact.bytes()),"comparison":compare(&docs[2],&r)}));}
let pairs=json!({"actualToNative":compare(&docs[0],&docs[1]),"nativeToHancom":compare(&docs[1],&docs[2]),"actualToHancom":compare(&docs[0],&docs[2])});for(i,name)in names.iter().enumerate(){assert_eq!(sha(&std::fs::read(repo.join(name)).unwrap()),inputs[i]["sha256"]);}
let result=json!({"candidateSource":"source-import-v7-compact80","compiledDocumentSourceSha256":sha(include_bytes!("../src/document_core/commands/document.rs")),"compiledWriterSourceSha256":sha(include_bytes!("../src/serializer/body_text.rs")),"inputs":inputs,"pairs":pairs,"reopenCycles":cycles,"inputsUnchanged":true,"fullSnapshotsWritten":false,"note":"Every published layout field is compared at existing0.2 tolerance. Raw native model comparison retains caches and raw IDs and is not the production TS resolved semantic reader. No source values are projected out to claim equivalence."});
let mut f=std::fs::OpenOptions::new().write(true).create_new(true).open(out.join("native-import-v7-hancom-readback.json")).unwrap();use std::io::Write;f.write_all(&serde_json::to_vec_pretty(&result).unwrap()).unwrap();assert_eq!(pairs["actualToNative"]["publishedGeometryDifferences"],0);assert_eq!(pairs["nativeToHancom"]["publishedGeometryDifferences"],0,"Hancom reflow differs; result retained");}
